"""
Workflow data transformation module for processing step outputs.
"""

import ast
import operator


# Allowed binary operators
_BIN_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
    ast.LShift: operator.lshift,
    ast.RShift: operator.rshift,
    ast.BitOr: operator.or_,
    ast.BitXor: operator.xor,
    ast.BitAnd: operator.and_,
}

# Allowed unary operators
_UNARY_OPS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
    ast.Not: operator.not_,
    ast.Invert: operator.invert,
}

# Allowed comparison operators
_CMP_OPS = {
    ast.Eq: operator.eq,
    ast.NotEq: operator.ne,
    ast.Lt: operator.lt,
    ast.LtE: operator.le,
    ast.Gt: operator.gt,
    ast.GtE: operator.ge,
    ast.Is: operator.is_,
    ast.IsNot: operator.is_not,
    ast.In: lambda a, b: a in b,
    ast.NotIn: lambda a, b: a not in b,
}


class SafeEvalError(Exception):
    """Raised when an unsafe expression is encountered."""
    pass


def _safe_eval(node, data):
    """Recursively evaluate an AST node in a restricted environment."""
    if isinstance(node, ast.Constant):
        return node.value
    elif isinstance(node, ast.Name):
        if node.id == 'input_data':
            return data
        elif node.id in ('True', 'False', 'None'):
            return {'True': True, 'False': False, 'None': None}[node.id]
        else:
            raise SafeEvalError(f"Use of name '{node.id}' is not allowed")
    elif isinstance(node, ast.Dict):
        keys = [_safe_eval(k, data) for k in node.keys]
        values = [_safe_eval(v, data) for v in node.values]
        return dict(zip(keys, values))
    elif isinstance(node, ast.List):
        return [_safe_eval(el, data) for el in node.elts]
    elif isinstance(node, ast.Tuple):
        return tuple(_safe_eval(el, data) for el in node.elts)
    elif isinstance(node, ast.Set):
        return {_safe_eval(el, data) for el in node.elts}
    elif isinstance(node, ast.Subscript):
        value = _safe_eval(node.value, data)
        if isinstance(node.slice, ast.Index):  # Python < 3.9 compatibility
            slice_val = _safe_eval(node.slice.value, data)
        else:
            slice_val = _safe_eval(node.slice, data)
        return value[slice_val]
    elif isinstance(node, ast.BinOp):
        op_type = type(node.op)
        if op_type not in _BIN_OPS:
            raise SafeEvalError(f"Binary operator '{type(node.op).__name__}' is not allowed")
        left = _safe_eval(node.left, data)
        right = _safe_eval(node.right, data)
        return _BIN_OPS[op_type](left, right)
    elif isinstance(node, ast.UnaryOp):
        op_type = type(node.op)
        if op_type not in _UNARY_OPS:
            raise SafeEvalError(f"Unary operator '{type(node.op).__name__}' is not allowed")
        operand = _safe_eval(node.operand, data)
        return _UNARY_OPS[op_type](operand)
    elif isinstance(node, ast.BoolOp):
        if isinstance(node.op, ast.And):
            result = True
            for val in node.values:
                result = _safe_eval(val, data)
                if not result:
                    return result
            return result
        elif isinstance(node.op, ast.Or):
            result = False
            for val in node.values:
                result = _safe_eval(val, data)
                if result:
                    return result
            return result
        else:
            raise SafeEvalError("Unknown boolean operator")
    elif isinstance(node, ast.Compare):
        left = _safe_eval(node.left, data)
        for op, comparator in zip(node.ops, node.comparators):
            op_type = type(op)
            if op_type not in _CMP_OPS:
                raise SafeEvalError(f"Comparison operator '{type(op).__name__}' is not allowed")
            right = _safe_eval(comparator, data)
            if not _CMP_OPS[op_type](left, right):
                return False
            left = right
        return True
    elif isinstance(node, ast.IfExp):
        test = _safe_eval(node.test, data)
        if test:
            return _safe_eval(node.body, data)
        else:
            return _safe_eval(node.orelse, data)
    elif isinstance(node, ast.Attribute):
        # Allow only specific attributes? For safety, disallow all.
        raise SafeEvalError("Attribute access is not allowed")
    elif isinstance(node, ast.Call):
        raise SafeEvalError("Function calls are not allowed")
    elif isinstance(node, ast.ListComp) or isinstance(node, ast.SetComp) or isinstance(node, ast.DictComp) or isinstance(node, ast.GeneratorExp):
        raise SafeEvalError("Comprehensions are not allowed")
    elif isinstance(node, ast.Lambda):
        raise SafeEvalError("Lambda expressions are not allowed")
    elif isinstance(node, ast.Slice):
        lower = _safe_eval(node.lower, data) if node.lower else None
        upper = _safe_eval(node.upper, data) if node.upper else None
        step = _safe_eval(node.step, data) if node.step else None
        return slice(lower, upper, step)
    else:
        raise SafeEvalError(f"Expression type '{type(node).__name__}' is not allowed")


def transform_step_data(transform_map_expr: str, input_data: dict) -> dict:
    """
    Transforms input data using a provided expression string.

    Args:
        transform_map_expr: A string representing a Python dictionary literal
                           that defines how to map input fields to output fields.
        input_data: Dictionary containing the input data from a previous step.

    Returns:
        A new dictionary with transformed data according to the expression.
    """
    try:
        tree = ast.parse(transform_map_expr, mode='eval')
        result = _safe_eval(tree.body, input_data)
        if not isinstance(result, dict):
            raise SafeEvalError("Expression must evaluate to a dictionary")
        return result
    except SafeEvalError as e:
        raise ValueError(f"Unsafe or invalid expression: {e}") from e
    except Exception as e:
        raise ValueError(f"Invalid expression: {e}") from e

"""
Workflow data transformation module for processing step outputs.
"""

import ast
import operator


class UnsafeExpressionError(ValueError):
    """Raised when the expression contains unsafe constructs."""
    pass


# Mapping of AST operator nodes to actual operator functions
_BIN_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
    ast.LShift: operator.lshift,
    ast.RShift: operator.rshift,
    ast.BitOr: operator.or_,
    ast.BitXor: operator.xor,
    ast.BitAnd: operator.and_,
}

_UNARY_OPS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
    ast.Not: operator.not_,
    ast.Invert: operator.invert,
}

_CMP_OPS = {
    ast.Eq: operator.eq,
    ast.NotEq: operator.ne,
    ast.Lt: operator.lt,
    ast.LtE: operator.le,
    ast.Gt: operator.gt,
    ast.GtE: operator.ge,
    ast.Is: operator.is_,
    ast.IsNot: operator.is_not,
    ast.In: lambda a, b: a in b,
    ast.NotIn: lambda a, b: a not in b,
}


def _safe_eval(node, env):
    """
    Recursively evaluate an AST node in a restricted environment.
    Only safe operations are allowed.
    """
    if isinstance(node, ast.Constant):
        return node.value
    elif isinstance(node, ast.Name):
        if node.id in env:
            return env[node.id]
        raise UnsafeExpressionError(f"Unknown variable: {node.id}")
    elif isinstance(node, ast.Dict):
        keys = [_safe_eval(k, env) for k in node.keys]
        values = [_safe_eval(v, env) for v in node.values]
        return dict(zip(keys, values))
    elif isinstance(node, ast.List):
        return [_safe_eval(el, env) for el in node.elts]
    elif isinstance(node, ast.Tuple):
        return tuple(_safe_eval(el, env) for el in node.elts)
    elif isinstance(node, ast.Set):
        return {_safe_eval(el, env) for el in node.elts}
    elif isinstance(node, ast.Subscript):
        value = _safe_eval(node.value, env)
        slice_val = _safe_eval(node.slice, env)
        return value[slice_val]
    elif isinstance(node, ast.BinOp):
        left = _safe_eval(node.left, env)
        right = _safe_eval(node.right, env)
        op_func = _BIN_OPS.get(type(node.op))
        if op_func is None:
            raise UnsafeExpressionError(f"Unsupported binary operator: {type(node.op).__name__}")
        return op_func(left, right)
    elif isinstance(node, ast.UnaryOp):
        operand = _safe_eval(node.operand, env)
        op_func = _UNARY_OPS.get(type(node.op))
        if op_func is None:
            raise UnsafeExpressionError(f"Unsupported unary operator: {type(node.op).__name__}")
        return op_func(operand)
    elif isinstance(node, ast.Compare):
        left = _safe_eval(node.left, env)
        for op, comparator in zip(node.ops, node.comparators):
            right = _safe_eval(comparator, env)
            op_func = _CMP_OPS.get(type(op))
            if op_func is None:
                raise UnsafeExpressionError(f"Unsupported comparison operator: {type(op).__name__}")
            if not op_func(left, right):
                return False
            left = right
        return True
    elif isinstance(node, ast.BoolOp):
        if isinstance(node.op, ast.And):
            result = True
            for value in node.values:
                result = _safe_eval(value, env)
                if not result:
                    return False
            return result
        elif isinstance(node.op, ast.Or):
            for value in node.values:
                result = _safe_eval(value, env)
                if result:
                    return True
            return False
        else:
            raise UnsafeExpressionError(f"Unsupported boolean operator: {type(node.op).__name__}")
    elif isinstance(node, ast.IfExp):
        test = _safe_eval(node.test, env)
        if test:
            return _safe_eval(node.body, env)
        else:
            return _safe_eval(node.orelse, env)
    else:
        raise UnsafeExpressionError(f"Unsupported AST node: {type(node).__name__}")


def transform_step_data(transform_map_expr: str, input_data: dict) -> dict:
    """
    Transforms input data using a provided expression string.

    The expression is safely evaluated using AST analysis. Only the variable
    `input_data` is available, along with constants True, False, None.
    Supported constructs: dictionary/list/tuple/set literals, arithmetic,
    comparison, logical operators, subscript access, and ternary expressions.

    Args:
        transform_map_expr: A string representing a Python dictionary literal
                           that defines how to map input fields to output fields.
        input_data: Dictionary containing the input data from a previous step.

    Returns:
        A new dictionary with transformed data according to the expression.

    Raises:
        UnsafeExpressionError: If the expression contains unsafe constructs.
        ValueError: If the expression does not evaluate to a dictionary.
    """
    try:
        tree = ast.parse(transform_map_expr, mode='eval')
    except SyntaxError as e:
        raise ValueError(f"Invalid expression syntax: {e}")

    # Restricted environment: only input_data and basic constants
    env = {
        'input_data': input_data,
        'True': True,
        'False': False,
        'None': None,
    }

    try:
        result = _safe_eval(tree.body, env)
    except UnsafeExpressionError as e:
        raise ValueError(f"Unsafe expression: {e}")

    if not isinstance(result, dict):
        raise ValueError("Expression must evaluate to a dictionary")

    return result
